"""Readable report/plot from frozen results, no training or selection."""
import json
from .pipeline import ROOT
from .research_report_text import markdown


def main():
    r=json.loads((ROOT/'docs/REGIONAL_MINIMUM_SUMMARY.json').read_text(encoding='utf-8'));s=r['selection'];m=s['dataset_meta']
    audit=json.loads((ROOT/'data/processed/regional-minimum/station-audit.json').read_text(encoding='utf-8'))
    diagnostic=s['diagnostic'];matched=s['matched'];passed=[n for n,g in s['gates'].items() if all(g.values())]
    fmt=lambda x:'—' if x is None else f'{x:.3f}'
    lines=['# Расширение обучения на другие станции и холодные эпизоды','',
           f"Выбран **{s['winner']}**. Диагностический региональный вариант **{diagnostic}** зафиксирован до открытия отложенных станций и контрольных2025–2026. Проверки2023–2024 прошли {len(passed)} из16 новых вариантов. Это отдельный исследовательский прогноз минимума; исходный детектор и полевой GFS не заменены.",'',
           '## Архив и валидность','',
           f"Проверены {len(audit['stations'])} станций по метаданным в пределах43–50°с.ш.,33–47°в.д. За2022–2024 подходят {len(m['sites'])}: не менее30 полных ночей в каждом весеннем сезоне. Архив содержит {sum(m['records'].values())} прогнозных станция-ночей; неполные факты остаются в архиве, но не входят в обучение и MAE. Все14 часов19–08МСК идут из одного GFS06UTC, с прогнозными температурой2м, RH2м, точкой росы2м, ветром10м и облачностью того же объекта.",
           'Ни фактическая температура будущей ночи, ни её факт холода не входят в признаки. Проверены GRIB-параметры, уровни, единицы, горизонт, сетка0.25°, контрольные суммы и доступность по архивному Last-Modified+10мин до условной выдачи18МСК. Это архивный proxy доступности, не измеренный SLA оперативного сервиса.',
           'Факты новых станций — NOAA ISD-Lite. Время округлено до часа, детальные исходные QC-флаги в Lite отсутствуют. Полнота не означает отсутствие всех ошибок; непрерывный минимум и температура цветка неизвестны. Факты исходной станции ISD/METAR сохранены, не заменены новым источником. [Описание NOAA](https://www.ncei.noaa.gov/products/land-based-station/integrated-surface-database), [формат и округление времени](https://www.ncei.noaa.gov/pub/data/noaa/isd-lite/isd-lite-format.pdf).','',
           '| Станция | Роль | Высота, м | Полных ночей2022/23/24 |','|---|---|---:|---|']
    for a in audit['stations']:
        if a['eligible']:lines.append(f"|{a['name']} ({a['id']})|{a['role']}|{a['elevation_m']:.0f}|{' / '.join(str(a['years'][str(y)]['complete_nights']) for y in [2022,2023,2024])}|")
    lines += ['', 'Изначальный hash-разделитель не дал пригодных отложенных станций. До декодирования GFS и оценки ошибок применён metadata-only fallback: два ранее не использованных сайта с минимальным SHA256(id). Так выделены SHPAKOVSKOYE и MINERALNYYE VODY. Отбор использовал полноту, а не холод или ошибку. Их файлы целей не загружаются функцией выбора модели. Остальные семь дополнительных станций и исходная используются для разработки.',
              'Высокогорная MESTIA включена и показана явно: её данные не означают переносимость модели на равнинный сад. Здесь нет выбранной площадки пилота, локальных измерений сада или подтверждённой биологической цели.','',
              '## Обучение и холодные эпизоды','',
              'Фолды2022→2023 и2022–2023→2024; финальное обучение2022–2023. Сравниваются Huber(alpha1) и Ridge(alpha100), веса холодных1/2, балансировка дат или холодных эпизодов, исходная станция или расширенный регион. Реестр16 вариантов фиксирован до расчёта контрольных лет. Признаки — те же15 прогнозных погодных характеристик, что у прежнего минимума, без ID станции и фактов.',
              'Исходный вес записи делится на число полных станций этой даты, затем применяются вес холодных1/2 и эпизодная поправка. Общая сумма нормируется к числу обучающих дат, а не числу станция-ночей. В варианте episode последовательные холодные даты с разрывом≤2дня объединяются, вес холодных записей делится на число холодных дат группы. Группы строятся только по обучающим фактам. Это инженерное приближение погодной волны, не доказательство независимости синоптических эпизодов. Тёплые ночи сохраняются; отрицательные случаи не размножаются.', '',
              '| Фолд | Обучение | Полных станция-ночей | Холодных станция-ночей | Холодных дат | Групп холодных дат |','|---|---|---:|---:|---:|---:|']
    for year in [2023,2024]:
        for name in [matched,diagnostic]:
            a=next(a for a in s['training'] if a['fold']['validation_year']==year and a['name']==name)
            lines.append(f"|{year}|{name}|{a['training_nights']}|{a['cold_site_nights']}|{a['cold_dates']}|{a['cold_episode_groups']}|")
    lines += ['', '## Выбор по2023–2024','',
              'Каждый год исходной станции проверяется отдельно: общая и холодная MAE, пропуски и ложные пересечения нуля не хуже прежнего точечного минимума. Каждый год дополнительных development-станций также проверяется отдельно: MAE с равным весом станций и холодная MAE, пропуски и ложные пересечения не хуже GFS. При провале хотя бы одного критерия вариант не выбирается. Ранжирование прошедших — холодная MAE исходной станции, затем общая; при отсутствии прошедших остаётся прежний минимум.',
              '**Пересечение нуля точечным минимумом — отдельная диагностика, не тревога детектора.** Основной детектор, порог0.25, маски и времена не менялись. Для новых станций он не объявляется валидным.', '',
              '| Вариант | MAE исходной станции, °C | Холодная MAE, °C | Ложных пересечений | Пропусков | Все критерии |','|---|---:|---:|---:|---:|---|']
    for name,a in s['validation']['primary'].items():
        lines.append(f"|{name}|{fmt(a['mae_c'])}|{fmt(a['cold_mae_c'])}|{a['false_alarms']}|{a['misses']}|{'база' if name in ['gfs','legacy'] else 'Да' if all(s['gates'][name].values()) else 'Нет'}|")
    lines += ['', 'Подробные показатели каждого года, станции, эпизодной ошибки и причины отказа сохранены в JSON. Пул не может скрыть ухудшение отдельного года. Настройки не менялись по отложенным станциям или2025–2026.','', '## Отложенные станции:2024','',
              'Проверка переносимости выполнена после фиксации выбора. Эти сайты не входят в fit или выбор, но даты совпадают с региональной валидацией и погода зависима; это не полностью независимый слепой погодный тест. Станционная модель здесь переносится только как исследовательский baseline, без разрешения на эксплуатацию.', '',
              '| Станция | Вариант | Полных ночей | Холодных | MAE, °C | Холодная MAE, °C | Ложных пересечений | Пропусков |','|---|---|---:|---:|---:|---:|---:|---:|']
    for label in ['gfs','legacy','diagnostic','matched_station']:
        for sid,a in r['spatial_2024']['scores'][label]['by_site'].items():
            lines.append(f"|{sid}|{label}|{a['nights']}|{a['cold_nights']}|{fmt(a['mae_c'])}|{fmt(a['cold_mae_c'])}|{a['false_alarms']}|{a['misses']}|")
    lines += ['', '## Контроль2025–2026 исходной станции','',
              'Контрольные годы ранее просмотрены в предыдущих экспериментах, поэтому нового слепого теста не заявляем. В этом эксперименте они не участвуют в обучении, весах, выборе или смене модели. Диагностический вариант не становится выбранным после просмотра контроля.', '',
              '| Год | Вариант | MAE, °C | Холодная MAE, °C | Ложных пересечений | Пропусков |','|---|---|---:|---:|---:|---:|']
    for year,z in r['seasons'].items():
        for label in ['gfs','legacy','selected','diagnostic','matched_station']:
            a=z['scores'][label];lines.append(f"|{year}|{label}|{fmt(a['mae_c'])}|{fmt(a['cold_mae_c'])}|{a['false_alarms']}|{a['misses']}|")
        b=z['paired_week_blocks_vs_legacy']['diagnostic'];lines += ['',f"{year}: изменение общей MAE регионального кандидата относительно прежнего минимума {b['mean_mae_delta_c']:+.3f}°C; описательный95% интервал по общим календарным неделям {b['interval_95_c'][0]:+.3f}…{b['interval_95_c'][1]:+.3f}°C. Все станции/даты внутри блока пересэмплируются вместе; волны могут пересекать границы недель.",'']
    lines += ['Сохранены все184 исходных точечных прогноза и полные объекты прежнего детектора, включая маски и расписание. Его контрольные тревоги прежние:2025 —6/6 обнаруженных,3 ложных;2026 —4/4,1 ложная. Это10 холодных ночей исходной станции, не гарантированная надёжность в саду.','',
              '## Решение для продукта','',
              ('Ни один новый вариант не прошёл все заранее заданные проверки. Расширение архива удалось; доказанного улучшения, удовлетворяющего политике без роста ложных пересечений, пока нет. Сохраняем прежний минимум и детектор. Более низкая отдельная MAE не оправдывает переключение после контроля.' if s['winner']=='legacy' else 'Выбранный вариант прошёл prior-проверки, однако остаётся исследовательским до независимой проверки сезона и измерений сада. Исходный детектор и полевая выдача сохранены.'),
              'Следующая проверка должна иметь новый заранее зафиксированный протокол и независимые локальные холодные события. Данные новых станций можно использовать в следующем prior-эксперименте, но нельзя объявлять уже просмотренные станции новым отложенным тестом. Валидация воздуха не подтверждает повреждения яблони, эффективность защиты или экономию.','',
              '## Воспроизведение','',
              '```powershell','.venv\\Scripts\\python.exe -m agro_checker.regional_data --audit','.venv\\Scripts\\python.exe -m agro_checker.regional_data --extract',
              '.venv\\Scripts\\python.exe -m agro_checker.regional_minimum_study --select-only','.venv\\Scripts\\python.exe -m agro_checker.regional_minimum_study',
              '.venv\\Scripts\\python.exe -m agro_checker.regional_minimum_report','```','',
              'Данные и модели уже сохранены; после контроля не переобучать и не редактировать научные источники/config на месте. Повторный selection проверяет контрольные суммы. Первичное расширенное скачивание —288 station-year запросов; для повторной работы использовать кэш.','',
              f"Фиксация выбора UTC{s['selection_saved_at_utc']}; SHA `{r['selection_sha256']}`.",'',
              '[Метрики и происхождение](REGIONAL_MINIMUM_SUMMARY.json). [Исходный минимум](MINIMUM_STUDY_REPORT.md). [Помощник агронома](AGRONOM_PRODUCT_REPORT.md).']
    (ROOT/'docs/REGIONAL_MINIMUM_REPORT.md').write_text(markdown(lines),encoding='utf-8')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10})
    fig,axes=plt.subplots(1,3,figsize=(13,4.6),layout='constrained');labels=['GFS','Прежний минимум','Региональный кандидат'];colors=['#607d8b','#25644c','#c27435']
    for ax,title,scores in [(axes[0],'Выбор2023–2024\nисходная станция',s['validation']['primary']),
                            (axes[1],'Отложенные станции2024\nпосле фиксации выбора',r['spatial_2024']['scores'])]:
        names=['gfs','legacy',diagnostic] if ax is axes[0] else ['gfs','legacy','diagnostic'];v=[scores[n]['cold_mae_c'] for n in names]
        bars=ax.bar(range(3),v,color=colors);ax.bar_label(bars,fmt='%.2f',padding=3);ax.set_xticks(range(3),labels,rotation=20,ha='right');ax.set_ylabel('MAE минимума холодных ночей, °C');ax.set_title(title);ax.set_ylim(0,max(v)*1.25);ax.spines[['top','right']].set_visible(False)
    ax=axes[2];x=[0,1];width=.24
    for j,(label,color) in enumerate(zip(['gfs','legacy','diagnostic'],colors)):
        values=[r['seasons'][str(y)]['scores'][label]['cold_mae_c'] for y in [2025,2026]]
        bars=ax.bar([v+(j-1)*width for v in x],values,width,color=color,label=labels[j]);ax.bar_label(bars,fmt='%.2f',padding=3,fontsize=9)
    ax.set_xticks(x,['2025','2026']);ax.set_ylabel('Холодная MAE, °C');ax.set_title('Ранее просмотренные контроли\nбез смены выбранной модели');ax.spines[['top','right']].set_visible(False);ax.legend(fontsize=8,loc='upper right');ax.set_ylim(0,max(r['seasons'][str(y)]['scores'][n]['cold_mae_c'] for y in [2025,2026] for n in ['gfs','legacy','diagnostic'])*1.4)
    fig.suptitle('Расширение архива: точность и ограничения переноса',fontsize=15);fig.savefig(ROOT/'docs/assets/regional-minimum-quality.png',dpi=150);plt.close(fig)
    print('Report and research plot saved.')


if __name__=='__main__':main()
